SELECT USER_PROFILE_ID,USERID as APP_LOGGED_IN_USER_ID,concat(COALESCE(detail.FIRST_NAME,""), ' ' , COALESCE(detail.LAST_NAME,"")) as APP_LOGGED_IN_USER_NAME, USERID,role.ROLEID as APP_LOGGED_IN_ROLE_ID, ROLENAME as APP_LOGGED_IN_ROLENAME,    FIRST_NAME,     MIDDLE_NAME,     LAST_NAME,     EMAIL_ADDRESS,     PHOTO,     MOBILE_NUMBER,     DATE_OF_BIRTH,     GENDER,     AE_GRAMPANCHAYAT_ID,     AE_CREATEDBY,     AE_UPDATEDBY,     AE_CREATIONDATE,     AE_UPDATIONDATE,     AE_DELETIONDATE,     AE_TRANSACTION_ID FROM USER_PROFILE detail left join USERMAPPING map on USERID=USER_PROFILE_ID and MAPPINGTYPE='USER_PROJECT_ROLE' and PROJECTID=0 left join ROLE role on map.ROLEID=role.ROLEID